package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;
/** Compare explicit local source snapshots. Every selected update is checked again at commit. */
final class ReferenceRefresh {
 static String fingerprint(JSONObject source)throws Exception{StringBuilder value=new StringBuilder();for(String key:new String[]{"type","id","title","body","at"}){String part=source.has(key)?String.valueOf(source.get(key)):"";value.append(part.length()).append(':').append(part);}return PronunciationPolicy.revision(value.toString());}
 static JSONObject currentSet(Context c,int index,long revision)throws Exception{JSONObject all=ReferenceSets.read(c);JSONArray sets=all.getJSONArray("items");if(all.optLong("revision")!=revision||index<0||index>=sets.length())throw new IOException("参照セットが更新されました。開き直してください");return sets.getJSONObject(index);}
 static JSONObject compare(JSONObject set,JSONObject catalog)throws Exception{JSONArray sources=set.getJSONArray("sources"),rows=new JSONArray();for(int i=0;i<sources.length();i++){JSONObject old=sources.getJSONObject(i),row=new JSONObject().put("index",i).put("old",old);try{JSONObject current=UnifiedRecords.resolve(catalog,old.getString("type"),old.getString("id"));String hash=fingerprint(current);row.put("state",fingerprint(old).equals(hash)?"unchanged":"changed").put("current",current).put("fingerprint",hash);}catch(IOException missing){row.put("state","unavailable");}rows.put(row);}return new JSONObject().put("items",rows).put("scope","元記録と保存時点のコピーを比較。選んで保存するまでセットは変えません。未取得・対象外・削除は区別できない場合があります。");}
 static synchronized void update(Context c,int index,long revision,JSONArray selected,JSONObject catalog)throws Exception{synchronized(ReferenceSets.class){JSONObject set=currentSet(c,index,revision);if(selected.length()<1||selected.length()>6)throw new IOException("更新する項目を1〜6件選んでください");JSONArray sources=new JSONArray(set.getJSONArray("sources").toString());java.util.HashSet<Integer> seen=new java.util.HashSet<>();for(int i=0;i<selected.length();i++){JSONObject choice=selected.getJSONObject(i);int at=choice.getInt("index");if(at<0||at>=sources.length()||!seen.add(at))throw new IOException("選択した項目を確認してください");JSONObject old=sources.getJSONObject(at),current=UnifiedRecords.resolve(catalog,old.getString("type"),old.getString("id"));if(!choice.getString("fingerprint").equals(fingerprint(current)))throw new IOException("比較後に元の記録が変わりました。比較をやり直してください");sources.put(at,current);}JSONObject next=ReferenceSets.checked(set.getString("name"),sources),all=ReferenceSets.read(c);if(all.optLong("revision")!=revision)throw new IOException("セットが更新されました。開き直してください");all.getJSONArray("items").put(index,next);all.put("revision",revision+1);ReviewStore.write(c,"reference-sets",all);}}
 private ReferenceRefresh(){}
}
